import{_ as t,C as r,c as s,o as i,a6 as a,G as d}from"./chunks/framework.BY05barL.js";const b=JSON.parse('{"title":"Algoritmos de Asignación de Memoria","description":"","frontmatter":{},"headers":[],"relativePath":"unidad2/algoritmos-asignacion.md","filePath":"unidad2/algoritmos-asignacion.md"}'),n={name:"unidad2/algoritmos-asignacion.md"};function l(u,e,m,c,p,g){const o=r("AllocationAlgorithmsSimulator");return i(),s("div",null,[e[0]||(e[0]=a('<h1 id="algoritmos-de-asignacion-de-memoria" tabindex="-1">Algoritmos de Asignación de Memoria <a class="header-anchor" href="#algoritmos-de-asignacion-de-memoria" aria-label="Permalink to &quot;Algoritmos de Asignación de Memoria&quot;">​</a></h1><p>Cuando llega un proceso, el SO tiene que elegir <strong>en qué hueco libre</strong> ponerlo. Cada algoritmo usa un criterio distinto:</p><table tabindex="0"><thead><tr><th>Algoritmo</th><th>Cómo elige el hueco</th><th>Ventaja</th><th>Desventaja</th></tr></thead><tbody><tr><td><strong>Primer ajuste</strong> (First Fit)</td><td>Recorre desde el principio y usa el <strong>primer</strong> hueco donde entra el proceso</td><td>Rápido: busca lo menos posible</td><td>Tiende a dejar huecos grandes a medio usar</td></tr><tr><td><strong>Próximo ajuste</strong> (Next Fit)</td><td>Igual que el primer ajuste, pero <strong>sigue buscando desde el último hueco asignado</strong> (no vuelve al principio)</td><td>Rápido</td><td>Aprovecha la memoria un poco peor que el primer ajuste</td></tr><tr><td><strong>Mejor ajuste</strong> (Best Fit)</td><td>Recorre <strong>todos</strong> los huecos y usa el <strong>más chico</strong> donde entra</td><td>No usa un hueco grande que puede servir después</td><td>Lento: busca en toda la lista. Deja huecos muy chicos que casi nunca sirven</td></tr><tr><td><strong>Peor ajuste</strong> (Worst Fit)</td><td>Recorre <strong>todos</strong> los huecos y usa el <strong>más grande</strong></td><td>El espacio que sobra es grande y puede servir</td><td>Lento: busca en toda la lista. Las simulaciones muestran que no es buena idea</td></tr></tbody></table><h2 id="pregunta-4" tabindex="-1">Pregunta 4 <a class="header-anchor" href="#pregunta-4" aria-label="Permalink to &quot;Pregunta 4&quot;">​</a></h2><p>Considere un sistema con intercambio, en el que la memoria posee particiones libres de tamaño fijo: 800Kb, 300Kb, 1500Kb, 600Kb, 700Kb, 1000Kb y 1200Kb. Estos huecos están dispuestos en el orden dado. Se tienen tres procesos de los siguientes tamaños 1000Kb, 800Kb y 700Kb.</p><p>Como las particiones son de <strong>tamaño fijo</strong>, cada proceso ocupa un hueco entero. Lo que sobra del hueco se desperdicia (en violeta en el simulador).</p><p>Ver también las <a href="https://ucasal-ssoo.vercel.app/tp2/13" target="_blank" rel="noreferrer">diapositivas del TP2</a>.</p><h2 id="simulador" tabindex="-1">Simulador <a class="header-anchor" href="#simulador" aria-label="Permalink to &quot;Simulador&quot;">​</a></h2>',8)),d(o),e[1]||(e[1]=a('<h2 id="preguntas" tabindex="-1">Preguntas <a class="header-anchor" href="#preguntas" aria-label="Permalink to &quot;Preguntas&quot;">​</a></h2><h3 id="a-¿que-huecos-seran-asignados-para-cada-algoritmo" tabindex="-1">a) ¿Qué huecos serán asignados para cada algoritmo? <a class="header-anchor" href="#a-¿que-huecos-seran-asignados-para-cada-algoritmo" aria-label="Permalink to &quot;a) ¿Qué huecos serán asignados para cada algoritmo?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Algoritmo</th><th>Proceso 1 (1000)</th><th>Proceso 2 (800)</th><th>Proceso 3 (700)</th></tr></thead><tbody><tr><td>Primer ajuste</td><td>1500</td><td>800</td><td>700</td></tr><tr><td>Próximo ajuste</td><td>1500</td><td>1000</td><td>1200</td></tr><tr><td>Mejor ajuste</td><td>1000</td><td>800</td><td>700</td></tr><tr><td>Peor ajuste</td><td>1500</td><td>1200</td><td>1000</td></tr></tbody></table><h3 id="b-¿cual-es-el-algoritmo-mas-rapido-y-cual-es-el-mas-lento" tabindex="-1">b) ¿Cuál es el algoritmo más rápido y cuál es el más lento? <a class="header-anchor" href="#b-¿cual-es-el-algoritmo-mas-rapido-y-cual-es-el-mas-lento" aria-label="Permalink to &quot;b) ¿Cuál es el algoritmo más rápido y cuál es el más lento?&quot;">​</a></h3><ul><li><strong>Más rápidos</strong>: primer ajuste y próximo ajuste, porque dejan de buscar apenas encuentran un hueco. En este ejemplo, el próximo ajuste recorre 7 bloques y el primer ajuste, 9.</li><li><strong>Más lentos</strong>: mejor ajuste y peor ajuste, porque siempre recorren todos los huecos (7 por proceso, 21 en total).</li></ul><h3 id="c-¿cual-es-el-algoritmo-que-aprovecha-mejor-la-memoria" tabindex="-1">c) ¿Cuál es el algoritmo que aprovecha mejor la memoria? <a class="header-anchor" href="#c-¿cual-es-el-algoritmo-que-aprovecha-mejor-la-memoria" aria-label="Permalink to &quot;c) ¿Cuál es el algoritmo que aprovecha mejor la memoria?&quot;">​</a></h3><p>El <strong>mejor ajuste</strong>: en este ejemplo cada proceso entra justo en su hueco y no desperdicia nada (0 KB). El primer ajuste desperdicia 500 KB, y el próximo ajuste y el peor ajuste, 1200 KB cada uno.</p><h3 id="d-¿como-mejorar-el-algoritmo-de-peor-ajuste" tabindex="-1">d) ¿Cómo mejorar el algoritmo de peor ajuste? <a class="header-anchor" href="#d-¿como-mejorar-el-algoritmo-de-peor-ajuste" aria-label="Permalink to &quot;d) ¿Cómo mejorar el algoritmo de peor ajuste?&quot;">​</a></h3><p><strong>Mejoras posibles:</strong></p><ul><li>Mantener la lista ordenada por tamaño (de mayor a menor)</li><li>Usar estructuras de datos más eficientes (heap máximo)</li><li><strong>Beneficio estadístico:</strong> Genera fragmentos grandes que pueden ser útiles para procesos futuros grandes</li></ul>',10))])}const j=t(n,[["render",l]]);export{b as __pageData,j as default};
